package io.github.azneotec.ticketing.catalogue;

import static org.assertj.core.api.Assertions.assertThat;

import java.io.IOException;
import java.nio.file.Files;
import java.nio.file.Path;
import org.junit.jupiter.api.Test;
import org.springframework.boot.test.web.server.LocalServerPort;
import org.springframework.web.client.RestClient;

/**
 * Keeps {@code docs/openapi.yaml} in step with the code. The spec is generated by springdoc from
 * the running app; this test fails if the committed file differs, so an API change can't land
 * without its spec. To regenerate: {@code ./gradlew :bootstrap:test --tests '*OpenApiSpecTest'
 * -PupdateOpenApi}.
 */
class OpenApiSpecTest extends IntegrationTestBase {

  // Gradle runs tests in the module directory (bootstrap/), so the repo root is one level up.
  private static final Path SPEC = Path.of("..", "docs", "openapi.yaml");

  @LocalServerPort int port;

  @Test
  void committedSpecMatchesTheCode() throws IOException {
    var generated =
        RestClient.create("http://localhost:" + port)
            .get()
            .uri("/v3/api-docs.yaml")
            .retrieve()
            .body(String.class);
    assertThat(generated).contains("openapi:").contains("/admin/events/{id}/publish");

    if (Boolean.getBoolean("openapi.update")) {
      Files.createDirectories(SPEC.getParent());
      Files.writeString(SPEC, generated);
    }
    assertThat(SPEC)
        .as("docs/openapi.yaml is out of date; regenerate it with -PupdateOpenApi")
        .exists()
        .hasContent(generated);
  }
}
